#!/usr/bin/env node
/**
 * Copy the generated IdP Prisma client into the build output.
 *
 * `packages/database` publishes `./dist/index.js`, and that file imports
 * `./idp-client/index.js`. The client is generated by Prisma as JavaScript into
 * `src/idp-client` (see the `output` in prisma/idp-schema.prisma), and `tsc`
 * only emits compiled TypeScript — it does not copy stray `.js`/`.d.ts` assets.
 * So the built package could not resolve its own client and every consumer died
 * at runtime with:
 *
 *   Cannot find module './idp-client/index.js'
 *
 * which surfaced as ~15 module-resolution failures and ~30 downstream
 * "Cannot read properties of undefined (reading 'findMany')" errors across the
 * API test suite.
 *
 * Node rather than a shell one-liner because no build step may require bash
 * (TRD ADR-010 — native Windows is a first-class, CI-verified target).
 */
import { cpSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, "..", "packages", "database");
const from = join(pkg, "src", "idp-client");
const to = join(pkg, "dist", "idp-client");

if (!existsSync(from)) {
  console.error(
    `Generated IdP client not found at ${from}.\n` +
      `Run \`pnpm db:generate\` before building @kannan19302/database.`,
  );
  process.exit(1);
}

mkdirSync(dirname(to), { recursive: true });
cpSync(from, to, { recursive: true });
console.log("Copied generated IdP client into dist/idp-client");
